/* This example demonstrates setting up and using an alternate signal stack for SIGUSR1. */

#define _XOPEN_SOURCE 700
#define _POSIX_C_SOURCE 200809L

#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define STACK_SIZE SIGSTKSZ // Standard minimum size defined in <signal.h>

void signal_handler(int sig) {
    printf("\n--- Signal %d received ---\n", sig);

    // Check if we are running on the alternate stack
    stack_t current_ss;
    if (sigaltstack(NULL, &current_ss) == 0 && (current_ss.ss_flags & SS_ONSTACK)) {
        printf("Successfully executed handler on alternate stack.\n");
    } else {
        printf("Error: Handler did not execute on alternate stack.\n");
    }

    _exit(EXIT_SUCCESS);
}

int main() {
    stack_t ss_config;
    struct sigaction sa;
    void *stack_mem = NULL;

    // 1. Allocate memory for the alternate stack
    if ((stack_mem = malloc(STACK_SIZE)) == NULL) {
        perror("malloc failed");
        return EXIT_FAILURE;
    }

    // 2. Define the stack configuration
    ss_config.ss_sp = stack_mem;
    ss_config.ss_size = STACK_SIZE;
    ss_config.ss_flags = 0; // Enable the stack

    // 3. Register the alternate stack using sigaltstack()
    if (sigaltstack(&ss_config, NULL) == -1) {
        perror("sigaltstack failed");
        free(stack_mem);
        return EXIT_FAILURE;
    }
    printf("Alternate signal stack registered (Size: %zu bytes).\n", STACK_SIZE);

    // 4. Set up the signal handler with SA_ONSTACK flag
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_ONSTACK; // Instruct kernel to use alternate stack

    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction failed");
        free(stack_mem);
        return EXIT_FAILURE;
    }

    printf("Configuration complete. Raising SIGUSR1 now...\n");
    raise(SIGUSR1); // Trigger the signal

    // The signal handler should exit the program
    free(stack_mem); 
    return EXIT_SUCCESS;
}
